    "text": "えっと、屋台で食べ物を販売する店の係りが食材の仕入れとか器材レンタルとかするんだけど。業者から見積もりを取ってくるんで、会計はそれを取りまとめて、予算を立てたりするんだよね。そのほか、最後収支を出すとこまで、お金に関すること全般。",
