    "unitId": "n1:task-comprehension:2013-12:3:line-4",
    "text": "ええと、ほかに決めなきゃいけないのは、ステージの係りと広報の係り。ステージの係りはイベントの企画と当日の進行役。広報の係りはホームページ作成とか。あっ、そういえば、大野さん、ウェブデザイン、勉強してたよね。",
