    "unitId": "n1:task-comprehension:2013-12:4:line-2",
    "text": "はい。ただ当日、参加者一人ひとりに経験の有無を確認して、グループ分けをする時間的な余裕があるかなあと思いまして。五十名以上の方が参加予定なので、資料代をいただくだけでも、手間がかかりますし。",
