    "text": "あのー、今年は健康診断よりもっと詳しい検査をしたいんで、人間ドックを受けたいんです。提携している病院で、人間ドックを受ける場合、たしか費用の補助があるんですよね。いままで、利用したことないんですけど、どうやって申し込んだらいいですか。",
